CREATE procedure [dbo].[SP_S_LoadSecurityTemplate] 
@Action INT,
@TemplateBaseId INT , 
@DefaultPermisionForNew bit

--Action 1 -> for load the exsisting templates and Action 2 -> for load the new (Autogenerated info)
As

BEGIN 
BEGIN TRY
     BEGIN TRANSACTION
			--getting the template list to show on select boxes
            if @Action=1
			BEGIN
				Declare @TemplateId INT,@DetailID INT
				select id,name  from AutoGenerateTemplatebases
			END
			Else if @Action=2 -- load the permision set for given template header
			BEGIN
				select FormId,DefaultViewAccess AS ViewAccess,DefaultInsertAccess AS InsertAccess,DefaultModifyAccess AS UpdateAccess,DefaultDeleteAccess AS DeleteAccess,DefaultPrintAccess PrintAccess,0 AS OverridedDefault  
				from AutoGenerateTemplates 
				where TemplateBaseId =@TemplateBaseId
			END
			ELSE IF @Action=3
			BEGIN

			select FormID 
			, @DefaultPermisionForNew as ViewAccess 
			, @DefaultPermisionForNew as InsertAccess 
			, @DefaultPermisionForNew as UpdateAccess 
			, @DefaultPermisionForNew as DeleteAccess 
			, @DefaultPermisionForNew as PrintAccess 
			, @DefaultPermisionForNew as OverridedDefault 
			from AutoGenerateInfoes
			END
            COMMIT TRANSACTION
 END TRY
   BEGIN CATCH
            IF @@TRANCOUNT > 0
                ROLLBACK TRAN --RollBack in case of Error
        END CATCH 
END




	--Get Data
